@Command([EditDocument]; "1");

@If(SendTo= "";	@Return(@Do(@Command([EditGotoField];"SendTo");	@Prompt([Ok];"Missing Value"; "Please select the Recipient!")));"");
@If(Topic= ""; 		@Return(@Do(@Command([EditGotoField];"Topic");		@Prompt([Ok];"Missing Value"; "Please enter the Topic!")));"");
@If(Category= "";	@Return(@Do(@Command([EditGotoField];"Category");	@Prompt([Ok];"Missing Value"; "Please select the Category!")));"");

FIELD CurrentAction :="Submitted";
FIELD NotifiedDate :=@Today;

@Command([FileSave]);

@MailSend(SendTo;QA:SCH;NULL;"Pancen QA Info : " + Topic ;NULL;"Please follow this doclink to the New QA Info  ---> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument]; "1");

FIELD CurrentAction := "Archive";
FIELD archivedate := @Today;
FIELD archiveby := @V3UserName;

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument]; "1");

FIELD CurrentAction:="Feedbacked";
@If(C="";FIELD C:=0;FIELD C:= C+1);

@If(C=0;FIELD FDBy_1:=@V3UserName;C=1;FIELD FDBy_2:=@V3UserName;C=2;FIELD FDBy_3:=@V3UserName;C=3;FIELD FDBy_4:=@V3UserName;C=4;FIELD FDBy_5:=@V3UserName;C=5;FIELD FDBy_6:=@V3UserName;C=6;FIELD FDBy_7:=@V3UserName;C=7;FIELD FDBy_8:=@V3UserName;C=8;FIELD FDBy_9:=@V3UserName;C=9;FIELD FDBy_10:=@V3UserName;"");

@If(C=0;FIELD SBDate_1:=@Today;C=1;FIELD SBDate_2:=@Today;C=2;FIELD SBDate_3:=@Today;C=3;FIELD SBDate_4:=@Today;C=4;FIELD SBDate_5:=@Today;C=5;FIELD SBDate_6:=@Today;C=6;FIELD SBDate_7:=@Today;C=7;FIELD SBDate_8:=@Today;C=8;FIELD SBDate_9:=@Today;C=9;FIELD SBDate_10:=@Today;"");

@Command([FileSave]);

@MailSend(QA;NULL;NULL;"Pancen QA Info : New Feedback Submitted For - " + Topic ;NULL;"Please follow this doclink to the New QA Info  ---> ";[IncludeDoclink]);

